use crate::standards::v1::subsets::any::io::sqlite::snapshot::En1992Snapshot;
use store::{ArtifactSqliteSnapshot,sqlite_snapshot::*};
fn fixture()->En1992Snapshot{let f:serde_json::Value=serde_json::from_str(include_str!("../🧫️fixtures/🔣️.json")).unwrap();serde_json::from_value(f["snapshot"].clone()).unwrap()}
fn project(s:&En1992Snapshot)->SqliteDatabase{s.to_sqlite_database(&mut SqliteSnapshotControl::new(&mut |_|true,SqliteDatabaseLimits::default())).unwrap()}
fn restore(d:&SqliteDatabase)->Result<En1992Snapshot,semio_framework_value::ValueError>{En1992Snapshot::from_sqlite_database(d,&mut SqliteSnapshotControl::new(&mut |_|true,SqliteDatabaseLimits::default()))}
#[test]fn sqlite_snapshot_en1992_all_entities_independent_sqlite_and_edit(){use std::io::Write;use std::process::{Command,Stdio};let s=fixture();let d=project(&s);assert_eq!(d.tables.len(),13);assert_eq!(restore(&d).unwrap(),s);let bytes=export_sqlite_database(&d,SqliteDatabaseLimits::default(),&mut |_|true).unwrap();let script="import{Database}from'bun:sqlite';const d=Database.deserialize(new Uint8Array(await Bun.stdin.arrayBuffer()));if(d.query('PRAGMA integrity_check').get().integrity_check!=='ok'||d.query('PRAGMA foreign_key_check').all().length)throw Error('integrity');if(d.query('SELECT count FROM en1992_bar_layer').get().count!==4294967295||d.query('SELECT legs FROM en1992_stirrups').get().legs!==4294967295)throw Error('nativeu32');d.query(\"UPDATE en1992_fire SET column_method='independent 日本'\").run();await Bun.write(Bun.stdout,d.serialize());d.close();";let mut child=Command::new("bun").args(["-e",script]).stdin(Stdio::piped()).stdout(Stdio::piped()).stderr(Stdio::piped()).spawn().unwrap();child.stdin.take().unwrap().write_all(&bytes).unwrap();let output=child.wait_with_output().unwrap();assert!(output.status.success(),"{}",String::from_utf8_lossy(&output.stderr));let back=restore(&import_sqlite_database(&output.stdout,SqliteDatabaseLimits::default(),&mut |_|true).unwrap()).unwrap();let mut expected=s;expected.members[0].fire.as_mut().unwrap().column_method="independent 日本".into();assert_eq!(back,expected);}
#[test]fn sqlite_snapshot_en1992_parent_order_width_bool_enum_and_ieee_guards(){let d=project(&fixture());for(table,index,value)in[("en1992_member",1,2),("en1992_bar_layer",1,999),("en1992_bar_layer",2,2),("en1992_member_action",1,999),("en1992_anchor_action",1,999),("en1992_bar_layer",5,-1),("en1992_bar_layer",5,4294967296),("en1992_stirrups",3,4294967296),("en1992_member",18,2)]{let mut bad=d.clone();bad.table_mut(table).unwrap().rows[0].values[index]=SqliteValue::Integer(value);assert!(restore(&bad).is_err());}for(index,value)in[(1,SqliteValue::Text("unknown annex".into())),(3,SqliteValue::Real(99.0)),(6,SqliteValue::Null),(7,SqliteValue::Text("unownedClass".into()))]{let mut bad=d.clone();bad.table_mut("en1992_document").unwrap().rows[0].values[index]=value;assert!(restore(&bad).is_err());}let mut bad=d.clone();let row=&mut bad.table_mut("en1992_fire").unwrap().rows[0];row.rowid=999;row.values[0]=SqliteValue::Integer(999);assert!(restore(&bad).is_err());let mut bad=d;let t=bad.table_mut("en1992_document").unwrap();t.sql=t.sql.replace("title TEXT NOT NULL","title TEXT");assert!(restore(&bad).is_err());}
#[test]fn sqlite_snapshot_en1992_limits_and_large_copy_cancellation(){let mut s=fixture();for limits in[SqliteDatabaseLimits{max_rows:1,..SqliteDatabaseLimits::default()},SqliteDatabaseLimits{max_value_bytes:16,..SqliteDatabaseLimits::default()}]{assert!(s.to_sqlite_database(&mut SqliteSnapshotControl::new(&mut |_|true,limits)).is_err());}assert!(s.to_sqlite_database(&mut SqliteSnapshotControl::new(&mut |_|false,SqliteDatabaseLimits::default())).is_err());let d=project(&s);assert!(En1992Snapshot::from_sqlite_database(&d,&mut SqliteSnapshotControl::new(&mut |_|false,SqliteDatabaseLimits::default())).is_err());assert!(En1992Snapshot::from_sqlite_database(&d,&mut SqliteSnapshotControl::new(&mut |_|true,SqliteDatabaseLimits{max_value_bytes:16,..SqliteDatabaseLimits::default()})).is_err());s.title="地".repeat(40000);let mut stopped=false;assert!(s.to_sqlite_database(&mut SqliteSnapshotControl::new(&mut |p|{if p.phase==SqliteSnapshotPhase::ProjectSnapshot&&p.completed>0{stopped=true;false}else{true}},SqliteDatabaseLimits::default())).is_err());assert!(stopped);for encoding in[SnapshotEncoding::Binary,SnapshotEncoding::Text]{assert!(s.preflight_sqlite_snapshot_encoding(encoding,&mut SqliteSnapshotControl::new(&mut |_|true,SqliteDatabaseLimits{max_value_bytes:65536,..SqliteDatabaseLimits::default()})).is_err());}}
#[test]fn sqlite_snapshot_en1992_actual_bare_erased_encodings_and_coordinates(){let s=fixture();let p=store::ArtifactCodec::bare::<En1992Snapshot,crate::En1992Mutation>(crate::EN1992_DOCUMENT_SCHEMA).snapshot_sqlite.unwrap();assert_eq!(p.snapshot_type,Some(std::any::TypeId::of::<En1992Snapshot>()));let dialect=store::io_schema::ArtifactDialect{artifact_kind:"s.norm.en1992".into(),standard:"1".into(),subset:"*".into()};for encoding in[SnapshotEncoding::Binary,SnapshotEncoding::Text]{let payload=match encoding{SnapshotEncoding::Binary=>store::io_schema::IoPayload::Binary(<En1992Snapshot as store::ArtifactPack>::encode_pack(&s)),SnapshotEncoding::Text=>store::io_schema::IoPayload::Text(<En1992Snapshot as store::ArtifactDsl>::print_dsl(&s))};let d=(p.export)(crate::EN1992_DOCUMENT_SCHEMA,&dialect,&payload,&mut SqliteSnapshotControl::new(&mut |_|true,SqliteDatabaseLimits::default())).unwrap().value;assert_eq!(project(&restore(&d).unwrap()),project(&s));assert_eq!((p.import)(crate::EN1992_DOCUMENT_SCHEMA,&dialect,d,encoding,&mut SqliteSnapshotControl::new(&mut |_|true,SqliteDatabaseLimits::default())).unwrap().value,payload);}let d=project(&s);for(artifact_kind,standard,subset)in[("s.norm.other","1","*"),("s.norm.en1992","v1","*"),("s.norm.en1992","1","named")]{let wrong=store::io_schema::ArtifactDialect{artifact_kind:artifact_kind.into(),standard:standard.into(),subset:subset.into()};assert!(s.validate_sqlite_snapshot_subset(&wrong,&d,&mut SqliteSnapshotControl::new(&mut |_|true,SqliteDatabaseLimits::default())).is_err());}}
#[semio_framework_async_macros::async_test]
async fn sqlite_snapshot_en1992_actual_declaration_typed_io_has_no_native_encoding(){use semio_framework_os_kernel::io::io_mechanism::{io_export_sqlite_snapshot,io_import_sqlite_snapshot};semio_framework_plugin::Plugin::<semio_framework_plugin::app::NoPluginApp>::builder("norm").label("EN1992 SQLite declaration").version("0.0.1").package_id("semio:norm").artifact(crate::declaration(crate::definition().unwrap()).unwrap()).try_build().unwrap();let s=fixture();let dialect=store::io_schema::ArtifactDialect{artifact_kind:"s.norm.en1992".into(),standard:"1".into(),subset:"*".into()};for encoding in[SnapshotEncoding::Binary,SnapshotEncoding::Text]{let mut phases=Vec::new();let bytes=io_export_sqlite_snapshot(&dialect,&s,encoding,SqliteDatabaseLimits::default(),&mut |p|{phases.push(p.phase);true}).await.unwrap().value;let restored=io_import_sqlite_snapshot::<En1992Snapshot>(&dialect,&bytes,SqliteDatabaseLimits::default(),&mut |_|true).await.unwrap().value;assert_eq!(project(&restored),project(&s));assert!(!phases.iter().any(|p|matches!(p,SqliteSnapshotPhase::EncodeNative|SqliteSnapshotPhase::DecodeNative)));}}
#[test]fn sqlite_snapshot_en1992_empty_root_and_optional_absence(){let mut s=fixture();let m=&mut s.members[0];m.stirrups=None;m.punching=None;m.prestress=None;m.fire=None;m.tightness=None;assert_eq!(restore(&project(&s)).unwrap(),s);for annex in[crate::document::AnnexChoice::En,crate::document::AnnexChoice::De]{s.annex=annex;s.concrete_grades.clear();s.reinforcement_grades.clear();s.prestress_steels.clear();s.members.clear();s.anchors.clear();let limits=SqliteDatabaseLimits{max_rows:1,..SqliteDatabaseLimits::default()};let d=s.to_sqlite_database(&mut SqliteSnapshotControl::new(&mut |_|true,limits)).unwrap();assert_eq!(d.tables.iter().map(|t|t.rows.len()).sum::<usize>(),1);assert_eq!(En1992Snapshot::from_sqlite_database(&d,&mut SqliteSnapshotControl::new(&mut |_|true,limits)).unwrap(),s);}}
fn every_word(bits:u64)->En1992Snapshot{let mut s=fixture();let w=f64::from_bits(bits);s.design_working_life_years=w;s.delta_c_dev=w;for v in &mut s.concrete_grades{v.f_ck=w;}for v in &mut s.reinforcement_grades{v.f_yk=w;v.e_s=w;v.k=w;v.eps_uk=w;}for v in &mut s.prestress_steels{v.f_pk=w;v.f_p0_1k=w;}for v in &mut s.members{v.width=w;v.height=w;v.effective_depth=w;v.cover=w;v.span=w;v.buckling_length=w;v.udl=w;v.hd_over_h=w;v.liquid_sigma_s=w;v.liquid_rho_p_eff=w;v.liquid_f_ct_eff=w;v.liquid_s_r_max=w;v.bridge_sigma_c=w;v.bridge_delta_sigma_s=w;for a in &mut v.longitudinal{a.diameter=w;a.anchorage_length=w;a.lap_length=w;a.aggregate_size=w;}if let Some(a)=&mut v.stirrups{a.diameter=w;a.spacing=w;}if let Some(a)=&mut v.punching{a.column_width=w;a.column_depth=w;a.asw=w;}if let Some(a)=&mut v.prestress{a.force=w;a.area=w;a.eccentricity=w;a.loss_ratio=w;}if let Some(a)=&mut v.fire{a.axis_distance=w;}for a in &mut v.actions{word_action(a,w);}}for v in &mut s.anchors{v.h_ef=w;v.f_uk=w;v.f_yk=w;v.a_s=w;v.d=w;v.c1=w;v.f_ck=w;for a in &mut v.actions{word_action(a,w);}}s}
fn word_action(a:&mut crate::LoadCaseActions,w:f64){a.g_k_line=w;a.q_k_line=w;a.point_force=w;a.m_k=w;a.n_k=w;a.v_k=w;a.t_k=w;a.v_k_punch=w;}
#[test]fn sqlite_snapshot_en1992_all_sixty_fields_have_independent_exact_word_oracle(){use std::io::Write;use std::process::{Command,Stdio};let f:serde_json::Value=serde_json::from_str(include_str!("../🧫️fixtures/🔣️.json")).unwrap();let script="import{Database}from'bun:sqlite';const d=Database.deserialize(new Uint8Array(await Bun.stdin.arrayBuffer()),{safeIntegers:true});const expected=BigInt.asIntN(64,BigInt('0x'+process.env.SEMIO_TEST_WORD));let count=0;for(const t of d.query(\"SELECT name FROM sqlite_schema WHERE type='table'\").all()){for(const c of d.query('PRAGMA table_info('+t.name+')').all()){if(!c.name.endsWith('_ieee754_bits'))continue;for(const v of d.query('SELECT '+c.name+' AS value FROM '+t.name).all()){if(v.value!==expected)throw Error('independent bit identity');count++;}}}if(count!==60)throw Error('all60scalars');await Bun.write(Bun.stdout,d.serialize());d.close();";for word in f["binary64Words"].as_array().unwrap(){let word=word.as_str().unwrap();let s=every_word(u64::from_str_radix(word,16).unwrap());let d=project(&s);let bytes=export_sqlite_database(&d,SqliteDatabaseLimits::default(),&mut |_|true).unwrap();let mut child=Command::new("bun").args(["-e",script]).env("SEMIO_TEST_WORD",word).stdin(Stdio::piped()).stdout(Stdio::piped()).stderr(Stdio::piped()).spawn().unwrap();child.stdin.take().unwrap().write_all(&bytes).unwrap();let output=child.wait_with_output().unwrap();assert!(output.status.success(),"{}",String::from_utf8_lossy(&output.stderr));let restored=restore(&import_sqlite_database(&output.stdout,SqliteDatabaseLimits::default(),&mut |_|true).unwrap()).unwrap();assert_eq!(project(&restored),d);}}
#[test]fn sqlite_snapshot_en1992_every_ieee_word_survives_actual_erased_native_encodings(){let f:serde_json::Value=serde_json::from_str(include_str!("../🧫️fixtures/🔣️.json")).unwrap();let p=store::ArtifactCodec::bare::<En1992Snapshot,crate::En1992Mutation>(crate::EN1992_DOCUMENT_SCHEMA).snapshot_sqlite.unwrap();let dialect=store::io_schema::ArtifactDialect{artifact_kind:"s.norm.en1992".into(),standard:"1".into(),subset:"*".into()};for word in f["binary64Words"].as_array().unwrap(){let s=every_word(u64::from_str_radix(word.as_str().unwrap(),16).unwrap());let expected=project(&s);for encoding in[SnapshotEncoding::Binary,SnapshotEncoding::Text]{let payload=match encoding{SnapshotEncoding::Binary=>store::io_schema::IoPayload::Binary(<En1992Snapshot as store::ArtifactPack>::encode_pack(&s)),SnapshotEncoding::Text=>store::io_schema::IoPayload::Text(<En1992Snapshot as store::ArtifactDsl>::print_dsl(&s))};let d=(p.export)(crate::EN1992_DOCUMENT_SCHEMA,&dialect,&payload,&mut SqliteSnapshotControl::new(&mut |_|true,SqliteDatabaseLimits::default())).unwrap().value;assert_eq!(project(&restore(&d).unwrap()),expected);let back=(p.import)(crate::EN1992_DOCUMENT_SCHEMA,&dialect,d,encoding,&mut SqliteSnapshotControl::new(&mut |_|true,SqliteDatabaseLimits::default())).unwrap().value;assert_eq!(back,payload);}}}
#[test]fn sqlite_snapshot_en1992_all_closed_native_enums_preserved(){use crate::{MemberKind,ExposureClass,SupportCondition,FireRating,TightnessClass,DuctilityClass};let mut s=fixture();for kind in[MemberKind::Beam,MemberKind::Slab,MemberKind::Column,MemberKind::Wall,MemberKind::FlatSlab,MemberKind::RibbedSlab,MemberKind::TensionMember,MemberKind::Bridge,MemberKind::LiquidRetaining]{s.members[0].kind=kind;assert_eq!(restore(&project(&s)).unwrap(),s);}for exposure in[ExposureClass::X0,ExposureClass::Xc1,ExposureClass::Xc2,ExposureClass::Xc3,ExposureClass::Xc4,ExposureClass::Xd1,ExposureClass::Xd2,ExposureClass::Xd3,ExposureClass::Xs1,ExposureClass::Xs2,ExposureClass::Xs3,ExposureClass::Xf1,ExposureClass::Xf2,ExposureClass::Xf3,ExposureClass::Xf4,ExposureClass::Xa1,ExposureClass::Xa2,ExposureClass::Xa3]{s.members[0].exposure=exposure;assert_eq!(restore(&project(&s)).unwrap(),s);}for support in[SupportCondition::SimplySupported,SupportCondition::Continuous,SupportCondition::Cantilever,SupportCondition::Fixed]{s.members[0].support=support;assert_eq!(restore(&project(&s)).unwrap(),s);}for rating in[FireRating::R30,FireRating::R60,FireRating::R90,FireRating::R120]{s.members[0].fire.as_mut().unwrap().rating=rating;assert_eq!(restore(&project(&s)).unwrap(),s);}for tightness in[None,Some(TightnessClass::Tc0),Some(TightnessClass::Tc1),Some(TightnessClass::Tc2)]{s.members[0].tightness=tightness;assert_eq!(restore(&project(&s)).unwrap(),s);}for ductility in[DuctilityClass::A,DuctilityClass::B,DuctilityClass::C]{s.reinforcement_grades[0].ductility=ductility;assert_eq!(restore(&project(&s)).unwrap(),s);}}
#[test]fn sqlite_snapshot_en1992_reconstruction_cancels_during_large_collection(){let mut s=fixture();s.concrete_grades=vec![s.concrete_grades[0].clone();513];let d=project(&s);let mut cancelled=false;assert!(En1992Snapshot::from_sqlite_database(&d,&mut SqliteSnapshotControl::new(&mut |p|{if p.phase==SqliteSnapshotPhase::ReconstructSnapshot&&p.completed==256{cancelled=true;false}else{true}},SqliteDatabaseLimits::default())).is_err());assert!(cancelled);}
#[test]fn sqlite_snapshot_en1992_controlled_native_owner_admits_physical_and_typed_state(){let s=fixture();for encoding in[SnapshotEncoding::Binary,SnapshotEncoding::Text]{let payload=match encoding{SnapshotEncoding::Binary=>store::io_schema::IoPayload::Binary(<En1992Snapshot as store::ArtifactPack>::encode_pack(&s)),SnapshotEncoding::Text=>store::io_schema::IoPayload::Text(<En1992Snapshot as store::ArtifactDsl>::print_dsl(&s))};let back=En1992Snapshot::decode_sqlite_snapshot_native(&payload,&mut SqliteSnapshotControl::new(&mut |_|true,SqliteDatabaseLimits::default())).unwrap();assert_eq!(project(&back),project(&s));assert!(En1992Snapshot::decode_sqlite_snapshot_native(&payload,&mut SqliteSnapshotControl::new(&mut |_|false,SqliteDatabaseLimits::default())).is_err());assert!(En1992Snapshot::decode_sqlite_snapshot_native(&payload,&mut SqliteSnapshotControl::new(&mut |_|true,SqliteDatabaseLimits{max_value_bytes:16,..SqliteDatabaseLimits::default()})).is_err());}}

#[test]
fn sqlite_snapshot_en1992_controlled_output_has_exact_wire_and_real_interior_admission(){
 let corpus:serde_json::Value=serde_json::from_str(include_str!("../🧫️fixtures/🔣️.json")).unwrap();let limits=&corpus["controlledOutput"];let count=limits["textBytes"].as_u64().unwrap() as usize;let after=limits["cancelAfter"].as_u64().unwrap() as usize;let tiny=limits["tinyBytes"].as_u64().unwrap() as usize;let mut s=fixture();s.title="x".repeat(count);let rows=project(&s).tables.iter().map(|table|table.rows.len()).sum();
 for encoding in[SnapshotEncoding::Binary,SnapshotEncoding::Text]{let expected=match encoding{SnapshotEncoding::Binary=>store::io_schema::IoPayload::Binary(<En1992Snapshot as store::ArtifactPack>::encode_pack(&s)),SnapshotEncoding::Text=>store::io_schema::IoPayload::Text(<En1992Snapshot as store::ArtifactDsl>::print_dsl(&s))};let actual=s.encode_sqlite_snapshot_native(encoding,&mut SqliteSnapshotControl::new(&mut |_|true,SqliteDatabaseLimits::default())).unwrap();assert!(actual==expected,"controlled owner wire differs");let bytes=match &expected{store::io_schema::IoPayload::Binary(v)=>v.len(),store::io_schema::IoPayload::Text(v)=>v.len()};assert!(s.encode_sqlite_snapshot_native(encoding,&mut SqliteSnapshotControl::new(&mut |_|true,SqliteDatabaseLimits{max_file_bytes:bytes,..SqliteDatabaseLimits::default()})).unwrap()==expected);let mut interior=false;let error=s.encode_sqlite_snapshot_native(encoding,&mut SqliteSnapshotControl::new(&mut |event|{let stop=event.phase==SqliteSnapshotPhase::EncodeNative&&event.total>after&&event.completed>=after&&event.completed<event.total;interior|=stop;!stop},SqliteDatabaseLimits::default())).unwrap_err();assert!(interior&&error.kind == semio_framework_value::ValueRefusalKind::Canceled,"{error}");assert!(s.encode_sqlite_snapshot_native(encoding,&mut SqliteSnapshotControl::new(&mut |_|true,SqliteDatabaseLimits{max_rows:rows,..SqliteDatabaseLimits::default()})).unwrap()==expected);for budget in[SqliteDatabaseLimits{max_rows:rows-1,..SqliteDatabaseLimits::default()},SqliteDatabaseLimits{max_file_bytes:bytes-1,..SqliteDatabaseLimits::default()},SqliteDatabaseLimits{max_value_bytes:tiny,..SqliteDatabaseLimits::default()},SqliteDatabaseLimits{max_rows:0,..SqliteDatabaseLimits::default()}]{assert!(s.encode_sqlite_snapshot_native(encoding,&mut SqliteSnapshotControl::new(&mut |_|true,budget)).is_err());}assert!(s.encode_sqlite_snapshot_native(encoding,&mut SqliteSnapshotControl::new(&mut |_|false,SqliteDatabaseLimits::default())).is_err());}
}

/// 📐️ The independent SQLite engine counts every physical semantic column, including IEEE fields.
fn en1992_independent_semantic_ceiling(source:&En1992Snapshot,expected_rows:usize){
 use std::{io::Write,process::{Command,Stdio}};
 let fixture:serde_json::Value=serde_json::from_str(include_str!("../🧫️fixtures/🔣️.json")).unwrap();
 let database=project(source);let bytes=export_sqlite_database(&database,SqliteDatabaseLimits::default(),&mut |_|true).unwrap();
 let mut child=Command::new("bun").arg("-e").arg(r####"import{Database}from'bun:sqlite';const db=Database.deserialize(new Uint8Array(await Bun.stdin.arrayBuffer()),{safeIntegers:true});try{if(db.query('PRAGMA integrity_check').get().integrity_check!=='ok'||db.query('PRAGMA foreign_key_check').all().length)throw Error('integrity');const tables=db.query("SELECT name FROM sqlite_schema WHERE type='table' ORDER BY name").all().map(({name})=>{const columns=db.query('PRAGMA table_info('+name+')').all(),expression=columns.map(({name})=>{const c='"'+name.replaceAll('"','""')+'"';return "CASE typeof("+c+") WHEN 'integer' THEN 8 WHEN 'real' THEN 8 WHEN 'text' THEN length(CAST("+c+" AS BLOB)) WHEN 'blob' THEN length("+c+") WHEN 'null' THEN 0 ELSE NULL END"}).join('+'),r=db.query('SELECT COUNT(*) AS rows,COALESCE(SUM('+expression+'),0) AS bytes FROM '+name).get();return{table:name,columns:columns.length,rows:Number(r.rows),semanticBytes:Number(r.bytes)}});console.log(JSON.stringify(tables));}finally{db.close()}"####).stdin(Stdio::piped()).stdout(Stdio::piped()).stderr(Stdio::piped()).spawn().unwrap();child.stdin.take().unwrap().write_all(&bytes).unwrap();let output=child.wait_with_output().unwrap();assert!(output.status.success(),"{}",String::from_utf8_lossy(&output.stderr));
 let tables:serde_json::Value=serde_json::from_slice(&output.stdout).unwrap();let tables=tables.as_array().unwrap();let widths:Vec<_>=tables.iter().map(|t|serde_json::json!([t["table"],t["columns"]])).collect();assert_eq!(serde_json::Value::Array(widths),fixture["semanticCells"]["tableWidths"]);let rows=tables.iter().map(|t|t["rows"].as_u64().unwrap()as usize).sum::<usize>();let cells=tables.iter().map(|t|t["semanticBytes"].as_u64().unwrap()as usize).sum::<usize>();assert_eq!(rows,expected_rows);
 let exact=SqliteDatabaseLimits{max_rows:rows,max_value_bytes:cells,..SqliteDatabaseLimits::default()};
 assert_eq!(source.to_sqlite_database(&mut SqliteSnapshotControl::new(&mut |_|true,exact)).unwrap(),database);
 let restored=En1992Snapshot::from_sqlite_database(&database,&mut SqliteSnapshotControl::new(&mut |_|true,exact)).unwrap();assert_eq!(project(&restored),database);restored.retire_sqlite_snapshot();
 for encoding in[SnapshotEncoding::Binary,SnapshotEncoding::Text]{
  let payload=match encoding{SnapshotEncoding::Binary=>store::io_schema::IoPayload::Binary(<En1992Snapshot as store::ArtifactPack>::encode_pack(source)),SnapshotEncoding::Text=>store::io_schema::IoPayload::Text(<En1992Snapshot as store::ArtifactDsl>::print_dsl(source))};
  assert_eq!(source.encode_sqlite_snapshot_native(encoding,&mut SqliteSnapshotControl::new(&mut |_|true,exact)).unwrap(),payload);
  let decoded=En1992Snapshot::decode_sqlite_snapshot_native(&payload,&mut SqliteSnapshotControl::new(&mut |_|true,exact)).unwrap();assert_eq!(project(&decoded),database);decoded.retire_sqlite_snapshot();
  for short in[SqliteDatabaseLimits{max_rows:rows-1,..exact},SqliteDatabaseLimits{max_value_bytes:cells-1,..exact}]{assert!(source.encode_sqlite_snapshot_native(encoding,&mut SqliteSnapshotControl::new(&mut |_|true,short)).is_err());assert!(En1992Snapshot::decode_sqlite_snapshot_native(&payload,&mut SqliteSnapshotControl::new(&mut |_|true,short)).is_err());}
 }
 for short in[SqliteDatabaseLimits{max_rows:rows-1,..exact},SqliteDatabaseLimits{max_value_bytes:cells-1,..exact}]{assert!(source.to_sqlite_database(&mut SqliteSnapshotControl::new(&mut |_|true,short)).is_err());assert!(En1992Snapshot::from_sqlite_database(&database,&mut SqliteSnapshotControl::new(&mut |_|true,short)).is_err());}
}

#[test]
fn sqlite_snapshot_en1992_complete_independent_semantic_ceiling(){
 let f:serde_json::Value=serde_json::from_str(include_str!("../🧫️fixtures/🔣️.json")).unwrap();let full=f["semanticCells"]["fullRows"].as_u64().unwrap()as usize;let absent_rows=f["semanticCells"]["absentRows"].as_u64().unwrap()as usize;
 en1992_independent_semantic_ceiling(&fixture(),full);
 for word in f["binary64Words"].as_array().unwrap(){en1992_independent_semantic_ceiling(&every_word(u64::from_str_radix(word.as_str().unwrap(),16).unwrap()),full);}
 let mut absent=fixture();for member in &mut absent.members{member.stirrups=None;member.punching=None;member.prestress=None;member.fire=None;member.tightness=None;}en1992_independent_semantic_ceiling(&absent,absent_rows);
}
